const deal = $('Deal Proposal Stage Webhook').first().json;
const config = $('Get Config').first().json;

/** n8n may receive flat HubSpot shape, { body }, or router envelope { webhookBody }. */
const unwrapPayload = (root) => {
  if (!root || typeof root !== 'object') return root;
  if (root.webhookBody && typeof root.webhookBody === 'object') return root.webhookBody;
  if (root.payload && typeof root.payload === 'object') return root.payload;
  return root;
};

const inner = unwrapPayload(deal);
const body =
  inner.body && typeof inner.body === 'object' && !Array.isArray(inner.body) ? inner.body : inner;
const props =
  body.properties && typeof body.properties === 'object' && !Array.isArray(body.properties)
    ? body.properties
    : body;

/** HubSpot router envelope may include merged contact props (preferred for client-facing fields). */
const merged =
  (deal.source && typeof deal.source === 'object' && deal.source.contactsMerged) ||
  (typeof deal.contactsMerged === 'object' && deal.contactsMerged) ||
  {};

const associatedContact = (() => {
  try {
    const c = $('Fetch Primary Contact').first().json;
    return (c && typeof c.properties === 'object' && c.properties) || (c && typeof c === 'object' ? c : {});
  } catch {
    return {};
  }
})();

const valueFrom = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim()) {
      return String(value).trim();
    }
  }
  return '';
};

const money = (value) => {
  if (value === undefined || value === null || value === '') return 0;
  const normalized = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(normalized) ? normalized : 0;
};

const titleCase = (value) => (value ? value.charAt(0).toUpperCase() + value.slice(1) : '');

/** PDF / UI: avoid em/en dashes in names and labels. */
const cleanDashes = (value) =>
  String(value ?? '')
    .replace(/\u2014/g, '-')
    .replace(/\u2013/g, '-')
    .replace(/\u2212/g, '-')
    .replace(/—/g, '-');

/** Parse line items from payload: arrays on body/properties, JSON string, or HubSpot hs_line_items JSON. */
const parseLineItemsRaw = () => {
  const candidates = [
    body.lineItems,
    body.line_items,
    props.lineItems,
    props.line_items,
    props.hs_line_items,
  ];
  for (const c of candidates) {
    if (Array.isArray(c) && c.length) return c;
    if (typeof c === 'string' && c.trim().startsWith('[')) {
      try {
        const parsed = JSON.parse(c);
        if (Array.isArray(parsed) && parsed.length) return parsed;
      } catch (e) {
        /* ignore */
      }
    }
  }
  return [];
};

const normalizeLineItems = (raw) => {
  return raw
    .map((x, i) => {
      if (!x || typeof x !== 'object') return null;
      const qty = Math.max(1, Number(x.quantity ?? x.qty ?? x.hs_quantity ?? 1) || 1);
      const unit = money(x.unitPrice ?? x.price ?? x.rate ?? x.hs_price ?? x.hs_unit_price);
      const lineTotal = money(x.amount ?? x.line_amount ?? x.total ?? x.line_total ?? x.hs_line_item_amount);
      const name = valueFrom(x.name, x.productName, x.title, x.hs_sku, `Line item ${i + 1}`);
      const sku = valueFrom(x.hs_sku, x.sku, '');
      const description = valueFrom(x.description, x.details, x.notes, '');
      let amount = lineTotal;
      if (!amount && unit) amount = unit * qty;
      if (!amount) amount = 0;
      return {
        name,
        sku,
        description,
        quantity: qty,
        unitPrice: unit || (qty ? amount / qty : amount),
        amount,
      };
    })
    .filter(Boolean);
};

const rawLineItems = parseLineItemsRaw();
const lineItems = normalizeLineItems(rawLineItems);
const lineItemsSubtotal = lineItems.reduce((s, li) => s + (Number(li.amount) || 0), 0);

const addressParts = [
  valueFrom(props.address, props.street, props.street_address, props.company_address),
  valueFrom(props.city, props.company_city),
  valueFrom(props.state, props.state_region, props.company_state),
  valueFrom(props.zip, props.zip_code, props.postal_code, props.company_zip),
  valueFrom(props.country, props.company_country),
].filter(Boolean);

const tierKey = valueFrom(props.tier).toLowerCase() || 'starter';
const tierInfo = (config.tiers && (config.tiers[tierKey] || config.tiers.starter)) || {
  name: titleCase(tierKey) || 'Starter',
  monthlyPrice: 0,
  setupFee: 0,
};

const rawPainSources = [
  valueFrom(props.deal_pain_points),
  valueFrom(props.painPoints),
  valueFrom(props.pain_point_summary),
].filter(Boolean);

const uniquePainSources = [...new Set(rawPainSources)];
const painPoints = uniquePainSources.join('\n\n');
const contactFirstName = valueFrom(associatedContact.firstname, props.contact_firstname, props.firstName, props.firstname);
const contactLastName = valueFrom(associatedContact.lastname, props.contact_lastname, props.lastName, props.lastname);
const contactName = cleanDashes([contactFirstName, contactLastName].filter(Boolean).join(' '));

const companyName = valueFrom(
  props.company,
  props.company_name,
  props.business_name,
  props.dealname,
  props.name,
);

const companyDisplay = (() => {
  const c = String(companyName || '').trim();
  if (c && c.toUpperCase() !== 'UNKNOWN') return cleanDashes(c);
  const m = valueFrom(merged.company, merged.business_name, merged.company_name);
  if (m && String(m).trim().toUpperCase() !== 'UNKNOWN') return cleanDashes(m);
  const dn = valueFrom(props.dealname, props.name);
  if (dn) {
    const short = dn.split(/\s*[–\u2013\u2014-]\s*/)[0].trim();
    return cleanDashes(short || dn);
  }
  return '';
})();

const industryDisplay = cleanDashes(
  valueFrom(props.industry, merged.industry, merged.website_intake_industry),
);

const contactEmailDisplay = cleanDashes(
  valueFrom(associatedContact.email, props.contact_email, props.email, merged.email, merged.contact_email),
);

const tierMonthly = money(tierInfo.monthlyPrice);
const upfrontDue = money(tierInfo.setupFee);
const explicitDealAmount = money(props.amount);
const explicitDiscount = money(
  valueFrom(
    props.hs_total_discount,
    props.total_discount,
    props.deal_discount,
    props.discount_amount,
    props.hs_discount,
  ),
);
let impliedDiscount = 0;
if (
  explicitDiscount <= 0 &&
  lineItemsSubtotal > 0 &&
  explicitDealAmount > 0 &&
  lineItemsSubtotal > explicitDealAmount + 0.005
) {
  impliedDiscount = lineItemsSubtotal - explicitDealAmount;
}
const totalDiscount = explicitDiscount > 0 ? explicitDiscount : impliedDiscount;

const tierAmount =
  explicitDealAmount > 0
    ? explicitDealAmount
    : lineItemsSubtotal > 0
      ? lineItemsSubtotal
      : upfrontDue;
const dealAmountForDisplay = explicitDealAmount > 0 ? explicitDealAmount : tierAmount;
const remainingTierBalance = Math.max(tierAmount - upfrontDue, 0);
const launchBalance = remainingTierBalance + tierMonthly;

const productList = lineItems.map((i) => ({
  sku: i.sku || '',
  name: i.name || '',
  price: i.unitPrice ?? (i.quantity ? i.amount / i.quantity : i.amount),
}));

return [
  {
    json: {
      clientName: cleanDashes(
        valueFrom(props.dealname, props.name, props.company, props.business_name, props.company_name),
      ),
      company: companyName,
      companyDisplay,
      industry: valueFrom(props.industry),
      industryDisplay,
      painPoints,
      painPointSummary: valueFrom(props.pain_point_summary, props.painPoints),
      rawPainPoints: valueFrom(props.deal_pain_points, painPoints),
      dealValue: tierAmount,
      amountLabel: valueFrom(props.amount),
      tierAmount,
      dealAmount: dealAmountForDisplay,
      lineItemsSubtotal,
      totalDiscount,
      tier: tierKey,
      tierLabel: tierInfo.name || titleCase(tierKey) || 'Starter',
      tierMonthly,
      monthlyCost: tierMonthly,
      upfrontDue,
      remainingTierBalance,
      launchBalance,
      finalDueAtPreLaunch: launchBalance,
      dealId: valueFrom(body.id, inner.id, deal.dealId, deal.id, body.dealId),
      contactEmail: valueFrom(
        associatedContact.email,
        props.contact_email,
        props.email,
        merged.email,
        merged.contact_email,
      ),
      contactEmailDisplay,
      contactPhone: valueFrom(associatedContact.phone, associatedContact.mobilephone, props.contact_phone, props.phone, props.mobilephone),
      contactFirstName,
      contactName: contactName || contactFirstName,
      address: addressParts.join(', '),
      city: valueFrom(props.city, props.company_city),
      state: valueFrom(props.state, props.state_region, props.company_state),
      postalCode: valueFrom(props.zip, props.zip_code, props.postal_code, props.company_zip),
      country: valueFrom(props.country, props.company_country),
      website: valueFrom(
        props.website,
        props.domain,
        props.company_domain,
        merged.website,
        merged.company_website,
        merged.hs_website,
      ),
      driveFolderId: valueFrom(props.client_drive_folder_id),
      lineItems,
      lineItemsTotal: lineItemsSubtotal,
      productList,
      config,
    },
  },
];

const raw = $('Call Claude API').first().json;
const text = (raw.content && raw.content[0] && raw.content[0].text) ? raw.content[0].text : '';
const d = $('Extract Deal Data').first().json;

const START = '<<<PAIN_SUMMARY>>>';
const END = '<<<END_PAIN_SUMMARY>>>';

let painSummaryForShell = '';
let bodyHtml = String(text || '').trim();

const si = bodyHtml.indexOf(START);
const ei = bodyHtml.indexOf(END);
if (si !== -1 && ei !== -1 && ei > si) {
  painSummaryForShell = bodyHtml.slice(si + START.length, ei).trim();
  bodyHtml = (bodyHtml.slice(0, si) + bodyHtml.slice(ei + END.length)).trim();
}

return [
  {
    json: {
      data: { text: bodyHtml },
      html: bodyHtml,
      painSummaryForShell,
      fileName: `IntraWeb - ${d.clientName} - Proposal.pdf`,
    },
  },
];

const claudeResult = $('Parse Claude Response').first().json;
const d = $('Extract Deal Data').first().json;
const config = d.config || {};
const branding = config.branding || {};
const owner = config.owner || {};
const companyName = owner.companyName || 'IntraWeb Technologies LLC';
const ownerEmail = owner.email || '';
const ownerPhone = owner.phone || '';
const ownerName = owner.name || 'John Schibelli';
const calendarLink = owner.calendarLink || '';
const bodyContent = (claudeResult.data ? claudeResult.data.text : claudeResult.html || '').trim();
const painSummaryForShell = String(claudeResult.painSummaryForShell || '').trim();
const clientName = d.clientName || 'Client';
const proposalDate = new Date().toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});
const validThrough = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});
const docId = d.dealId ? `DEAL-${String(d.dealId).slice(0, 12)}` : `PROP-${Date.now().toString(36).toUpperCase()}`;

const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const noEmDash = (value) =>
  String(value ?? '')
    .replace(/\u2014/g, '-')
    .replace(/\u2013/g, '-')
    .replace(/\u2212/g, '-')
    .replace(/—/g, '-');

const formatCurrency = (value) => {
  const numeric = Number(value || 0);
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(Number.isFinite(numeric) ? numeric : 0);
};

const logoHtml = (() => {
  const b64 = branding.logoPdfBase64 || branding.logoDarkBase64;
  const url = branding.logoUrlDark || branding.logoUrl;
  if (b64 && String(b64).trim()) {
    const src = String(b64).startsWith('data:') ? b64 : `data:image/png;base64,${b64}`;
    return `<img class="doc-header__logo" src="${src}" alt="IntraWeb" height="36" />`;
  }
  if (url && String(url).trim()) {
    return `<img class="doc-header__logo" src="${escapeHtml(url)}" alt="IntraWeb" height="36" />`;
  }
  return `<div class="doc-header__wordmark" aria-hidden="true">IntraWeb</div>`;
})();

/** Short themes for PDF - no raw intake dump, JSON, or PII. */
const summarizeIntakeForPdf = () => {
  const summary = String(d.painPointSummary || '').trim();
  if (summary) {
    const parts = summary
      .split(/[,;]\s*/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (parts.length) return noEmDash(parts.map((p) => `• ${p}`).join('\n'));
  }
  let raw = String(d.rawPainPoints || d.painPoints || '').trim();
  if (!raw) return 'No intake themes were captured for this opportunity.';
  raw = raw.split(/\n-{3,}\n/)[0].trim();
  raw = raw.replace(/Website intake \(JSON\):[\s\S]*?(?=\n-{3,}|\n===|$)/gi, '');
  raw = raw.replace(/Website intake \(structured fields\):[\s\S]*$/i, '');
  const lines = raw.split('\n').filter((ln) => {
    const t = ln.trim();
    if (!t) return false;
    if (/^(email|phone|name|firstname|lastname|business|location)\s*:/i.test(t)) return false;
    if (/^===\s*Website intake/i.test(t)) return false;
    return true;
  });
  raw = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  if (raw.length > 2400) raw = `${raw.slice(0, 2400).trim()}…`;
  return noEmDash(raw || 'No intake themes were captured for this opportunity.');
};

const intakeThemesText = summarizeIntakeForPdf();
const intakeThemesHtml = `<p class="quote quote--themes">${escapeHtml(intakeThemesText).replace(/\n/g, '<br/>')}</p>`;

const contactDisplay = d.contactName || d.contactFirstName || '';
const lineItems = Array.isArray(d.lineItems) ? d.lineItems : [];
const lineItemsSubtotal =
  Number(d.lineItemsSubtotal) ||
  lineItems.reduce((s, x) => s + (Number(x.amount) || 0), 0);
const discPdf = Math.max(0, Number(d.totalDiscount) || 0);
const dealAmtPdf = Number(d.dealAmount) || 0;
const tierAmtPdf = Number(d.tierAmount) || 0;

/** When line items exist, quoted total follows the table (subtotal − discounts), not a mismatched HubSpot deal amount. */
const finalQuotedPdf =
  lineItemsSubtotal > 0
    ? Math.max(0, lineItemsSubtotal - discPdf)
    : dealAmtPdf > 0
      ? dealAmtPdf
      : tierAmtPdf;

const isRecurringLineItem = (name) => {
  const n = String(name || '').toLowerCase();
  return /\bretainer\b/.test(n) || /\bmaintenance\b/.test(n) || /\bmonthly\b/.test(n);
};

const monthlyFromLineItems = lineItems
  .filter((li) => isRecurringLineItem(li.name))
  .reduce((s, li) => s + (Number(li.amount) || 0), 0);

const displayMonthlyRecurring =
  monthlyFromLineItems > 0 ? monthlyFromLineItems : Number(d.tierMonthly) || 0;

const upfrontPdf =
  lineItemsSubtotal > 0 ? Math.round(lineItemsSubtotal * 0.33 * 100) / 100 : Number(d.upfrontDue) || 0;

const afterUpfront = Math.max(0, finalQuotedPdf - upfrontPdf);
const launchBalancePdf = afterUpfront + displayMonthlyRecurring;

const tierMonthlyText = formatCurrency(displayMonthlyRecurring);
const upfrontDueText = formatCurrency(upfrontPdf);
const launchBalanceText = formatCurrency(launchBalancePdf);

const snapshotCompanyDisplay = noEmDash(String(d.companyDisplay || '').trim());
const snapshotCompanyCell = snapshotCompanyDisplay || 'Not specified';

const heroDisplayName = noEmDash(clientName || snapshotCompanyDisplay);

const snapshotEmail = noEmDash(
  String(d.contactEmailDisplay || d.contactEmail || '').trim(),
);
const snapshotIndustry = noEmDash(
  String(d.industryDisplay || d.industry || '').trim(),
);
const snapshotWebsite = noEmDash(String(d.website || '').trim());
const snapshotAddress = noEmDash(String(d.address || '').trim());

const monthlyRowLabel =
  monthlyFromLineItems > 0
    ? 'Monthly recurring (retainer / maintenance from line items)'
    : 'Monthly retainer (tier template)';

const lineItemsRowsHtml = (() => {
  const rows = [];
  if (lineItems.length) {
    for (const li of lineItems) {
      rows.push(
        `<tr><td>${escapeHtml(li.name || 'Item')}</td><td class="num">${escapeHtml(formatCurrency(li.amount))}</td></tr>`,
      );
    }
    rows.push(
      `<tr class="line-table__subtotal"><td>Subtotal (line items)</td><td class="num">${escapeHtml(formatCurrency(lineItemsSubtotal))}</td></tr>`,
    );
    if (discPdf > 0.005) {
      rows.push(
        `<tr class="line-table__discount"><td>Discounts</td><td class="num">-${escapeHtml(formatCurrency(discPdf))}</td></tr>`,
      );
    }
    rows.push(
      `<tr class="line-table__quoted"><td><strong>Quoted total</strong></td><td class="num"><strong>${escapeHtml(formatCurrency(finalQuotedPdf))}</strong></td></tr>`,
    );
  } else {
    rows.push(
      `<tr><td>Tier / package (${escapeHtml(d.tierLabel || d.tier || '')})</td><td class="num">${escapeHtml(formatCurrency(d.tierAmount))}</td></tr>`,
    );
    if (discPdf > 0.005) {
      rows.push(
        `<tr class="line-table__discount"><td>Discounts</td><td class="num">-${escapeHtml(formatCurrency(discPdf))}</td></tr>`,
      );
    }
    rows.push(
      `<tr class="line-table__quoted"><td><strong>Quoted total</strong></td><td class="num"><strong>${escapeHtml(formatCurrency(finalQuotedPdf || d.tierAmount))}</strong></td></tr>`,
    );
  }
  return rows.join('');
})();

const calendarHtml = calendarLink
  ? `<p class="doc-body__cta"><a class="cta-pill" href="${escapeHtml(calendarLink)}">Book approval call</a></p>`
  : '';

const safeBodyContent =
  bodyContent ||
  '<h2 class="doc-prose-h2">Executive Summary</h2><p class="body-text">Proposal content could not be generated.</p>';

const bodyInner = (() => {
  if (!safeBodyContent) return '';
  if (/^\s*</.test(safeBodyContent)) return safeBodyContent;
  return safeBodyContent
    .split(/\n\n+/)
    .map((block) => {
      const t = block.trim();
      if (!t) return '';
      return `<p class="body-text">${escapeHtml(t).replace(/\n/g, '<br/>')}</p>`;
    })
    .join('');
})();

const painShellPlain = noEmDash(
  painSummaryForShell.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
);
const usePainShell = painShellPlain.replace(/\s+/g, ' ').length > 48;
const painShellSection = usePainShell
  ? `<section class="doc-section doc-section--pain-shell">
        <h2 class="doc-section__title"><span class="doc-section__accent" aria-hidden="true"></span>What we heard</h2>
        <p class="body-text pain-shell">${escapeHtml(painShellPlain).replace(/\n/g, '<br/>')}</p>
      </section>`
  : '';
const intakeThemesSection = usePainShell
  ? ''
  : `<section class="doc-section doc-section--intake-themes">
        <h2 class="doc-section__title"><span class="doc-section__accent" aria-hidden="true"></span>Themes from intake</h2>
        <div class="callout callout--orange">
          ${intakeThemesHtml}
        </div>
      </section>`;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Proposal - ${escapeHtml(clientName)} - ${escapeHtml(companyName)}</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap" rel="stylesheet" />
  <style>
    :root {
      --iw-slate-950: #0d1117;
      --iw-slate-900: #141b26;
      --iw-slate-800: #1c2636;
      --iw-slate-700: #253347;
      --iw-slate-600: #344659;
      --iw-slate-500: #4a6075;
      --iw-slate-400: #6b8399;
      --iw-slate-300: #96aebe;
      --iw-slate-200: #c4d1da;
      --iw-slate-100: #e4eaef;
      --iw-slate-50: #f2f5f8;
      --iw-teal: #00c2a8;
      --iw-teal-light: #00dfc8;
      --iw-teal-dim: #007a6a;
      --iw-teal-ghost: #e0f8f5;
      --iw-orange: #f26419;
      --iw-orange-dim: #c04e0e;
      --iw-orange-ghost: #fef0e8;
      --iw-white: #ffffff;
      --iw-off-white: #f8fafb;
      --iw-print-footer-block: 0.55in;
    }
    @page {
      size: 8.5in 11in;
      margin: 0;
    }
    * {
      box-sizing: border-box;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
    html,
    body {
      margin: 0;
      padding: 0;
      background: var(--iw-slate-50);
      color: var(--iw-slate-700);
      font-family: 'DM Sans', system-ui, sans-serif;
    }
    .iw-page {
      width: 100%;
      max-width: none;
      min-height: 10in;
      margin: 0;
      background: var(--iw-slate-50);
      color: var(--iw-slate-700);
    }
    @media print {
      .iw-page {
        width: 100%;
        min-height: 0;
        margin: 0;
      }
    }
    .doc-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 14px 0.45in;
      background: var(--iw-slate-950);
      border-bottom: 3px solid var(--iw-teal);
      color: var(--iw-white);
    }
    .doc-header__logo {
      height: 36px;
      width: auto;
      display: block;
    }
    .doc-header__wordmark {
      font-size: 18px;
      font-weight: 700;
      letter-spacing: 0.04em;
      color: var(--iw-white);
    }
    .doc-header__doc-type {
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--iw-slate-300);
    }
    .doc-header__doc-id {
      font-size: 10pt;
      font-weight: 600;
      color: var(--iw-white);
      margin-top: 4px;
      text-align: right;
    }
    .doc-hero {
      background: var(--iw-slate-900);
      padding: 28px 0.45in 26px;
      color: var(--iw-white);
    }
    .doc-hero__label {
      display: inline-block;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--iw-orange);
      margin-bottom: 10px;
    }
    .doc-hero__label::before {
      content: '';
      margin-right: 0;
      color: var(--iw-orange);
    }
    .doc-hero__title {
      margin: 0 0 10px;
      font-size: 24pt;
      font-weight: 700;
      line-height: 1.15;
      color: var(--iw-white);
    }
    .doc-hero__subtitle {
      margin: 0;
      max-width: none;
      font-size: 11pt;
      line-height: 1.55;
      color: var(--iw-slate-300);
    }
    .doc-meta-bar {
      display: flex;
      flex-wrap: wrap;
      padding: 0 0.45in;
      background: var(--iw-slate-800);
      color: var(--iw-slate-100);
      font-size: 9.5pt;
