return [{ json: { html, fileName: `IntraWeb - ${d.clientName} - Proposal.pdf` } }];

const pdf = $('Call PDF Service').first();
const folder = $('Create folder').first();
const fileName = $('Prep PDF Input').first().json.fileName || 'document.pdf';
if (!folder?.json?.id) throw new Error('Create folder: missing id — check Drive node output.');
const raw = pdf.binary || {};
const keys = Object.keys(raw);
if (!keys.length) throw new Error('Call PDF Service: no binary — keep Call PDF → this node; Create folder must not sit between them.');
const dataKey = raw.data ? 'data' : keys[0];
return [{ json: { fileName, _clientFolderId: folder.json.id }, binary: { data: raw[dataKey] } }];

const extractItem = $('Extract Deal Data').first();
const uploadOut = $('Upload to Drive').first();
if (!extractItem?.json) {
  throw new Error('Prep Alert needs upstream data: run from the start of the workflow (or use "Execute previous nodes" / pin data on Extract Deal Data + Upload to Drive).');
}
const d = extractItem.json;
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';

return [{
  json: {
    message: driveLink ? `Proposal ready for ${d.clientName} — set Status to Approved to send: ${driveLink}` : `Proposal ready for ${d.clientName} — set Status to Approved to send. (Drive link unavailable.)`,
    priority: 'info'
  }
}];

const d = $('Extract Deal Data').first().json;
const uploadOut = $('Upload to Drive').first();
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';
const to = String(
  d.contactEmail ||
  d.contactEmailDisplay ||
  '',
).trim();
if (!to) throw new Error('No contact email found for proposal send. Set HubSpot contact_email or the associated contact email before sending.');

/** Resend: [{ filename, content }] with content = base64 (see SW: Send Email via Resend). */
const pdfBase64 = String($('Extract PDF Base64').first().json.pdfBase64 || '').trim();
if (!pdfBase64 || pdfBase64 === 'filesystem-v2') {
  throw new Error('Extract PDF Base64: missing/invalid base64 content for attachment.');
}
const fileName = String(
  $('Prep PDF Input').first().json.fileName || 'proposal.pdf',
).replace(/[\/]/g, '-');
const attachments = [{ filename: fileName, content: pdfBase64 }];

return [{
  json: {
    to,
    subject: `Your IntraWeb proposal is ready — ${d.clientName}`,
    html: `<p>Hi ${d.contactFirstName || 'there'},</p><p>Your proposal is attached. I've outlined exactly what we'll build, the timeline, and the investment.</p>${driveLink ? `<p>You can also <a href="${driveLink}" style="color:#0d9488;text-decoration:none;font-weight:600;">view it in Google Drive here</a>.</p>` : ''}<p>Take a look and let me know if you have any questions. When you're ready to move forward, reply to this email and I'll send the contract for e-signature.</p><p>— John<br/>${d.config?.owner?.companyName || 'IntraWeb'}</p>`,
    workflowName: 'SYS 03 — Proposal and Contract Delivery',
    attachments,
  }
}];

return [{
  json: {
    workflowName: 'SYS 03 — Proposal and Contract Delivery',
    contactName: $('Extract Deal Data').first().json.clientName,
    phone: '',
    eventType: 'proposal_sent',
    status: 'success',
    notes: `Deal value: $${$('Extract Deal Data').first().json.dealValue}`
  }
}];

const d = $('Extract Deal Data').first().json;
const uploadOut = $('Upload to Drive').first();
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';
function esc(x) { return String(x ?? '').replace(/'/g, "''"); }
const dealId = String(d.dealId || '').trim();
const statusDetail = 'Pending Review | $' + (d.dealValue || 0) + ' | ' + (d.tier || '') + ' | ' + (d.contactEmail || '');
const q = "INSERT INTO public.os_contracts_queue (queue_type,hubspot_deal_id,queue_date,client_name,drive_link,status,proposal_status_detail) VALUES ('proposal','" + esc(dealId) + "',CURRENT_DATE,'" + esc(d.clientName) + "','" + esc(driveLink) + "','Pending Review','" + esc(statusDetail) + "') ON CONFLICT (hubspot_deal_id,queue_type) DO UPDATE SET client_name = EXCLUDED.client_name, drive_link = EXCLUDED.drive_link, status = EXCLUDED.status, proposal_status_detail = EXCLUDED.proposal_status_detail, queue_date = EXCLUDED.queue_date, updated_at = now();";
return [{ json: { _sql: q } }];

const deal = $('Fetch Deal With Associations').first().json;
const contacts = deal.associations?.contacts?.results || [];
const contactId = contacts.map((c) => c.id).find(Boolean) || '';
return [{ json: { contactId, hasContact: Boolean(contactId) } }];

const deal = $('Deal Proposal Stage Webhook').first().json;
const config = $('Get Config').first().json;

/** n8n may receive flat HubSpot shape, { body }, or router envelope { webhookBody }. */
const unwrapPayload = (root) => {
  if (!root || typeof root !== 'object') return root;
  if (root.webhookBody && typeof root.webhookBody === 'object') return root.webhookBody;
  if (root.payload && typeof root.payload === 'object') return root.payload;
  return root;
};

const inner = unwrapPayload(deal);
const body =
  inner.body && typeof inner.body === 'object' && !Array.isArray(inner.body) ? inner.body : inner;
const props =
  body.properties && typeof body.properties === 'object' && !Array.isArray(body.properties)
    ? body.properties
    : body;

/** HubSpot router envelope may include merged contact props (preferred for client-facing fields). */
const merged =
  (deal.source && typeof deal.source === 'object' && deal.source.contactsMerged) ||
  (typeof deal.contactsMerged === 'object' && deal.contactsMerged) ||
  {};

const associatedContact = (() => {
  try {
    const c = $('Fetch Primary Contact').first().json;
    return (c && typeof c.properties === 'object' && c.properties) || (c && typeof c === 'object' ? c : {});
  } catch {
    return {};
  }
})();

const valueFrom = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim()) {
      return String(value).trim();
    }
  }
  return '';
};

const money = (value) => {
  if (value === undefined || value === null || value === '') return 0;
  const normalized = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(normalized) ? normalized : 0;
};

const titleCase = (value) => (value ? value.charAt(0).toUpperCase() + value.slice(1) : '');

/** PDF / UI: avoid em/en dashes in names and labels. */
const cleanDashes = (value) =>
  String(value ?? '')
    .replace(/\u2014/g, '-')
    .replace(/\u2013/g, '-')
    .replace(/\u2212/g, '-')
    .replace(/—/g, '-');

/** Parse line items from payload: arrays on body/properties, JSON string, or HubSpot hs_line_items JSON. */
const parseLineItemsRaw = () => {
  const candidates = [
    body.lineItems,
    body.line_items,
    props.lineItems,
    props.line_items,
    props.hs_line_items,
  ];
  for (const c of candidates) {
    if (Array.isArray(c) && c.length) return c;
    if (typeof c === 'string' && c.trim().startsWith('[')) {
      try {
        const parsed = JSON.parse(c);
        if (Array.isArray(parsed) && parsed.length) return parsed;
      } catch (e) {
        /* ignore */
      }
    }
  }
  return [];
};

const normalizeLineItems = (raw) => {
  return raw
    .map((x, i) => {
      if (!x || typeof x !== 'object') return null;
      const qty = Math.max(1, Number(x.quantity ?? x.qty ?? x.hs_quantity ?? 1) || 1);
      const unit = money(x.unitPrice ?? x.price ?? x.rate ?? x.hs_price ?? x.hs_unit_price);
      const lineTotal = money(x.amount ?? x.line_amount ?? x.total ?? x.line_total ?? x.hs_line_item_amount);
      const name = valueFrom(x.name, x.productName, x.title, x.hs_sku, `Line item ${i + 1}`);
      const sku = valueFrom(x.hs_sku, x.sku, '');
      const description = valueFrom(x.description, x.details, x.notes, '');
      let amount = lineTotal;
      if (!amount && unit) amount = unit * qty;
      if (!amount) amount = 0;
      return {
        name,
        sku,
        description,
        quantity: qty,
        unitPrice: unit || (qty ? amount / qty : amount),
        amount,
      };
    })
    .filter(Boolean);
};

const rawLineItems = parseLineItemsRaw();
const lineItems = normalizeLineItems(rawLineItems);
const lineItemsSubtotal = lineItems.reduce((s, li) => s + (Number(li.amount) || 0), 0);

const addressParts = [
  valueFrom(props.address, props.street, props.street_address, props.company_address),
  valueFrom(props.city, props.company_city),
  valueFrom(props.state, props.state_region, props.company_state),
  valueFrom(props.zip, props.zip_code, props.postal_code, props.company_zip),
  valueFrom(props.country, props.company_country),
].filter(Boolean);

const tierKey = valueFrom(props.tier).toLowerCase() || 'starter';
const tierInfo = (config.tiers && (config.tiers[tierKey] || config.tiers.starter)) || {
  name: titleCase(tierKey) || 'Starter',
  monthlyPrice: 0,
  setupFee: 0,
};

const rawPainSources = [
  valueFrom(props.deal_pain_points),
  valueFrom(props.painPoints),
  valueFrom(props.pain_point_summary),
].filter(Boolean);

const uniquePainSources = [...new Set(rawPainSources)];
const painPoints = uniquePainSources.join('\n\n');
const contactFirstName = valueFrom(associatedContact.firstname, props.contact_firstname, props.firstName, props.firstname);
const contactLastName = valueFrom(associatedContact.lastname, props.contact_lastname, props.lastName, props.lastname);
const contactName = cleanDashes([contactFirstName, contactLastName].filter(Boolean).join(' '));

const companyName = valueFrom(
  props.company,
  props.company_name,
  props.business_name,
  props.dealname,
  props.name,
);

const companyDisplay = (() => {
  const c = String(companyName || '').trim();
  if (c && c.toUpperCase() !== 'UNKNOWN') return cleanDashes(c);
