    }
    .proposal-body .body-text,
    .proposal-body p {
      font-size: 10pt;
      line-height: 1.75;
      color: var(--iw-slate-700);
    }
    .proposal-body h2,
    .doc-prose-h2 {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 12pt;
      font-weight: 700;
      margin: 24px 0 12px;
