      font-size: 9pt;
      color: var(--iw-slate-500);
      line-height: 1.5;
      margin-top: 8px;
    }
    @media print {
      html,
      body {
        height: auto;
      }
      main.doc-body > section:not(.proposal-body) {
        break-inside: auto;
        page-break-inside: auto;
      }
      .doc-body > section:not(.proposal-body) > .doc-section__title {
        break-after: avoid-page;
        page-break-after: avoid;
      }
      .doc-hero {
        break-after: avoid-page;
        page-break-after: avoid;
      }
      .doc-section__title {
        break-after: avoid-page;
        page-break-after: avoid;
        break-inside: avoid;
      }
      .kv-grid {
        break-inside: avoid-page;
        page-break-inside: avoid;
      }
      .line-table thead {
        display: table-header-group;
      }
      .line-table tbody tr {
        break-inside: avoid-page;
        page-break-inside: avoid;
      }
      .proposal-body h2,
      .doc-prose-h2 {
        break-after: avoid-page;
        page-break-after: avoid;
        break-inside: avoid;
      }
      .proposal-body div[style*="display:grid"] > div,
      .proposal-body div[style*="display: grid"] > div {
        break-inside: avoid-page;
        page-break-inside: avoid;
      }
    }
  </style>
</head>
<body>
  <div class="iw-page">
    <header class="doc-header">
      <div class="doc-header__left">${logoHtml}</div>
      <div>
        <div class="doc-header__doc-type">Project Proposal</div>
        <div class="doc-header__doc-id">${escapeHtml(docId)}</div>
      </div>
    </header>

    <section class="doc-hero">
      <div class="doc-hero__label">Project Proposal</div>
      <h1 class="doc-hero__title">${escapeHtml(heroDisplayName)}</h1>
      <p class="doc-hero__subtitle">Delivery-focused implementation scope, commercial summary, and next steps, aligned to the operational context captured for this opportunity.</p>
    </section>

    <div class="doc-meta-bar">
      <div class="doc-meta-bar__item">
        <div class="doc-meta-bar__k">Prepared for</div>
        <div class="doc-meta-bar__v">${escapeHtml(clientName)}</div>
      </div>
      <div class="doc-meta-bar__item">
        <div class="doc-meta-bar__k">Prepared on</div>
        <div class="doc-meta-bar__v">${escapeHtml(proposalDate)}</div>
      </div>
      <div class="doc-meta-bar__item">
        <div class="doc-meta-bar__k">Account manager</div>
        <div class="doc-meta-bar__v">${escapeHtml(ownerName)}</div>
      </div>
      <div class="doc-meta-bar__item">
        <div class="doc-meta-bar__k">Valid through</div>
        <div class="doc-meta-bar__v">${escapeHtml(validThrough)}</div>
      </div>
    </div>

    <main class="doc-body">
      <section>
        <h2 class="doc-section__title"><span class="doc-section__accent" aria-hidden="true"></span>Client snapshot</h2>
        <div class="kv-grid kv-grid--3col">
          <div><div class="kv-k">Client</div><div class="kv-v">${escapeHtml(clientName)}</div></div>
          <div><div class="kv-k">Company</div><div class="kv-v">${escapeHtml(snapshotCompanyCell)}</div></div>
          <div><div class="kv-k">Primary contact</div><div class="kv-v">${escapeHtml(contactDisplay)}</div></div>
          <div><div class="kv-k">Email</div><div class="kv-v">${escapeHtml(snapshotEmail || 'Not specified')}</div></div>
          <div><div class="kv-k">Phone</div><div class="kv-v">${escapeHtml(noEmDash(String(d.contactPhone || '').trim()) || 'Not specified')}</div></div>
          <div><div class="kv-k">Industry</div><div class="kv-v">${escapeHtml(snapshotIndustry || 'Not specified')}</div></div>
          <div><div class="kv-k">Website</div><div class="kv-v">${escapeHtml(snapshotWebsite || 'Not specified')}</div></div>
          <div style="grid-column: span 2"><div class="kv-k">Address</div><div class="kv-v">${escapeHtml(snapshotAddress || 'Not specified')}</div></div>
        </div>
      </section>

      ${painShellSection}
      ${intakeThemesSection}

      <section>
        <h2 class="doc-section__title"><span class="doc-section__accent" aria-hidden="true"></span>Investment summary</h2>
        <table class="line-table">
          <thead><tr><th>Item</th><th>Amount</th></tr></thead>
          <tbody>
            ${lineItemsRowsHtml}
            <tr class="line-table__schedule"><td colspan="2">Payment timing (estimate; final cadence on invoice)</td></tr>
            <tr><td>${escapeHtml(monthlyRowLabel)}</td><td class="num">${escapeHtml(tierMonthlyText)}</td></tr>
            <tr><td>${escapeHtml(lineItemsSubtotal > 0 ? 'Upfront due (33% of line-item subtotal)' : 'Upfront due')}</td><td class="num">${escapeHtml(upfrontDueText)}</td></tr>
            <tr class="line-table__total"><td>Launch balance (estimate)</td><td class="num">${escapeHtml(launchBalanceText)}</td></tr>
          </tbody>
        </table>
        <p class="fine-print">Launch balance estimate = quoted total minus upfront plus first month of recurring (retainer/maintenance from line items when present, otherwise tier monthly). Final amounts on invoice.</p>
      </section>

      <section class="proposal-body">
        ${bodyInner}
        <hr class="divider" />
        <p class="body-text" style="margin-bottom: 4px"><strong>${escapeHtml(companyName)}</strong>${ownerEmail ? ` · ${escapeHtml(ownerEmail)}` : ''}${ownerPhone ? ` · ${escapeHtml(ownerPhone)}` : ''}</p>
        ${calendarHtml}
      </section>
    </main>

    <footer class="doc-footer">
      <div class="doc-footer__brand">IntraWeb</div>
      <div class="doc-footer__conf">Confidential - prepared for ${escapeHtml(clientName)}. Distribution outside the parties requires written consent.</div>
      <div class="doc-footer__page">Page 1</div>
    </footer>
  </div>
</body>
</html>`;

return [{ json: { html, fileName: `IntraWeb - ${d.clientName} - Proposal.pdf` } }];

const pdf = $('Call PDF Service').first();
const folder = $('Create folder').first();
const fileName = $('Prep PDF Input').first().json.fileName || 'document.pdf';
if (!folder?.json?.id) throw new Error('Create folder: missing id — check Drive node output.');
const raw = pdf.binary || {};
const keys = Object.keys(raw);
if (!keys.length) throw new Error('Call PDF Service: no binary — keep Call PDF → this node; Create folder must not sit between them.');
const dataKey = raw.data ? 'data' : keys[0];
return [{ json: { fileName, _clientFolderId: folder.json.id }, binary: { data: raw[dataKey] } }];

const extractItem = $('Extract Deal Data').first();
const uploadOut = $('Upload to Drive').first();
if (!extractItem?.json) {
  throw new Error('Prep Alert needs upstream data: run from the start of the workflow (or use "Execute previous nodes" / pin data on Extract Deal Data + Upload to Drive).');
}
const d = extractItem.json;
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';

return [{
  json: {
    message: driveLink ? `Proposal ready for ${d.clientName} — set Status to Approved to send: ${driveLink}` : `Proposal ready for ${d.clientName} — set Status to Approved to send. (Drive link unavailable.)`,
    priority: 'info'
  }
}];

const d = $('Extract Deal Data').first().json;
const uploadOut = $('Upload to Drive').first();
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';
const to = String(
  d.contactEmail ||
  d.contactEmailDisplay ||
  '',
).trim();
if (!to) throw new Error('No contact email found for proposal send. Set HubSpot contact_email or the associated contact email before sending.');

/** Resend: [{ filename, content }] with content = base64 (see SW: Send Email via Resend). */
const pdfBase64 = String($('Extract PDF Base64').first().json.pdfBase64 || '').trim();
if (!pdfBase64 || pdfBase64 === 'filesystem-v2') {
  throw new Error('Extract PDF Base64: missing/invalid base64 content for attachment.');
}
const fileName = String(
  $('Prep PDF Input').first().json.fileName || 'proposal.pdf',
).replace(/[\/]/g, '-');
const attachments = [{ filename: fileName, content: pdfBase64 }];

return [{
  json: {
    to,
    subject: `Your IntraWeb proposal is ready — ${d.clientName}`,
    html: `<p>Hi ${d.contactFirstName || 'there'},</p><p>Your proposal is attached. I've outlined exactly what we'll build, the timeline, and the investment.</p>${driveLink ? `<p>You can also <a href="${driveLink}" style="color:#0d9488;text-decoration:none;font-weight:600;">view it in Google Drive here</a>.</p>` : ''}<p>Take a look and let me know if you have any questions. When you're ready to move forward, reply to this email and I'll send the contract for e-signature.</p><p>— John<br/>${d.config?.owner?.companyName || 'IntraWeb'}</p>`,
    workflowName: 'SYS 03 — Proposal and Contract Delivery',
    attachments,
  }
}];

return [{
  json: {
    workflowName: 'SYS 03 — Proposal and Contract Delivery',
    contactName: $('Extract Deal Data').first().json.clientName,
    phone: '',
    eventType: 'proposal_sent',
    status: 'success',
    notes: `Deal value: $${$('Extract Deal Data').first().json.dealValue}`
  }
}];

const d = $('Extract Deal Data').first().json;
const uploadOut = $('Upload to Drive').first();
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';
function esc(x) { return String(x ?? '').replace(/'/g, "''"); }
const dealId = String(d.dealId || '').trim();
const statusDetail = 'Pending Review | $' + (d.dealValue || 0) + ' | ' + (d.tier || '') + ' | ' + (d.contactEmail || '');
const q = "INSERT INTO public.os_contracts_queue (queue_type,hubspot_deal_id,queue_date,client_name,drive_link,status,proposal_status_detail) VALUES ('proposal','" + esc(dealId) + "',CURRENT_DATE,'" + esc(d.clientName) + "','" + esc(driveLink) + "','Pending Review','" + esc(statusDetail) + "') ON CONFLICT (hubspot_deal_id,queue_type) DO UPDATE SET client_name = EXCLUDED.client_name, drive_link = EXCLUDED.drive_link, status = EXCLUDED.status, proposal_status_detail = EXCLUDED.proposal_status_detail, queue_date = EXCLUDED.queue_date, updated_at = now();";
return [{ json: { _sql: q } }];

const deal = $('Fetch Deal With Associations').first().json;
const contacts = deal.associations?.contacts?.results || [];
const contactId = contacts.map((c) => c.id).find(Boolean) || '';
return [{ json: { contactId, hasContact: Boolean(contactId) } }];
